`timescale 1ns / 1ps
// Testbench: run lab1 core on rom.mem/ram.mem, check WB-stage writes.
module lab1_tb;
    reg clk, rst;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'd0),
        .debug_data(),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0)
    );

    initial begin
        clk = 0;
        rst = 1;
        #4 rst = 0;
    end
    always #1 clk = ~clk;

    integer errors = 0;
    integer checks = 0;

    // expected writes: checked when (PC_WB, rd) matches and value is compared
    task check(input [31:0] pc, input [4:0] rd, input [31:0] val);
        begin
            checks = checks + 1;
            if (core.reg_MEM_WB.PCurrent_WB == pc && core.reg_MEM_WB.RegWrite_WB &&
                core.reg_MEM_WB.rd_WB == rd) begin
                if (core.mux_WB.o !== val) begin
                    errors = errors + 1;
                    $display("FAIL PC=%h rd=x%0d got=%h exp=%h", pc, rd, core.mux_WB.o, val);
                end
            end
        end
    endtask

    // monitor every WB write, record latest write per PC
    reg [31:0] wb_val [0:1023];
    reg [4:0]  wb_rd  [0:1023];
    reg        wb_hit [0:1023];
    always @(posedge clk) begin
        if (!rst && core.reg_MEM_WB.RegWrite_WB && core.reg_MEM_WB.rd_WB != 0) begin
            wb_val[core.reg_MEM_WB.PCurrent_WB[9:0]] <= core.mux_WB.o;
            wb_rd [core.reg_MEM_WB.PCurrent_WB[9:0]] <= core.reg_MEM_WB.rd_WB;
            wb_hit[core.reg_MEM_WB.PCurrent_WB[9:0]] <= 1'b1;
        end
    end

    task expect(input [31:0] pc, input [4:0] rd, input [31:0] val);
        begin
            checks = checks + 1;
            if (wb_hit[pc[9:0]] !== 1'b1) begin
                errors = errors + 1;
                $display("FAIL PC=%h: no write to x%0d observed", pc, rd);
            end
            else if (wb_rd[pc[9:0]] !== rd || wb_val[pc[9:0]] !== val) begin
                errors = errors + 1;
                $display("FAIL PC=%h exp x%0d=%h got x%0d=%h", pc, rd, val,
                         wb_rd[pc[9:0]], wb_val[pc[9:0]]);
            end
        end
    endtask

    integer i;
    initial begin
        for (i = 0; i < 1024; i = i + 1) wb_hit[i] = 0;
        #2000;
        expect(32'h04, 5'd2, 32'h00000008);
        expect(32'h08, 5'd4, 32'h00000010);
        expect(32'h0C, 5'd1, 32'h00000018);
        expect(32'h10, 5'd1, 32'h00000017);
        expect(32'h14, 5'd5, 32'h00000014);
        expect(32'h18, 5'd6, 32'hFFFF0000);
        expect(32'h1C, 5'd7, 32'h0FFF0000);
        expect(32'h20, 5'd1, 32'h00000008);
        expect(32'h24, 5'd1, 32'h00000000);
        expect(32'h28, 5'd1, 32'h00000018);

