module lab3_tb;
    reg clk, rst;
    wire [7:0] uart_char;
    wire uart_valid;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'd0),
        .debug_data(),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0),
        .sim_uart_char_out(uart_char),
        .sim_uart_char_valid(uart_valid)
    );

