    integer errors = 0;
    initial begin
        #4000000;
        $display("");
        // after both sorts, arrays at 0x14 and 0x64 must be 0..19
        for (i = 0; i < 20; i = i + 1) begin
            if ({core.data_ram.data[20+4*i+3], core.data_ram.data[20+4*i+2],
                 core.data_ram.data[20+4*i+1], core.data_ram.data[20+4*i]} !== i) begin
                errors = errors + 1;
                $display("FAIL arr1[%0d] = %h", i, {core.data_ram.data[20+4*i+3],
                    core.data_ram.data[20+4*i+2], core.data_ram.data[20+4*i+1],
                    core.data_ram.data[20+4*i]});
            end
            // select_sort produces descending order: b[i] == N-1-i
            if ({core.data_ram.data[100+4*i+3], core.data_ram.data[100+4*i+2],
                 core.data_ram.data[100+4*i+1], core.data_ram.data[100+4*i]} !== 19 - i) begin
                errors = errors + 1;
                $display("FAIL arr2[%0d] = %h", i, {core.data_ram.data[100+4*i+3],
                    core.data_ram.data[100+4*i+2], core.data_ram.data[100+4*i+1],
                    core.data_ram.data[100+4*i]});
            end
        end
        if (errors == 0) $display("LAB3 PASS: both arrays sorted");
        else             $display("LAB3 FAIL: %0d errors", errors);
        $finish;
    end

