`timescale 1ns / 1ps

module FU_ALU(
    input clk, EN,
    input[3:0] ALUControl,
    input[31:0] ALUA, ALUB,
    output[31:0] res,
    output zero, overflow,
    output finish
);

    localparam ALU_ADD  = 4'b0001;
    localparam ALU_SUB  = 4'b0010;
    localparam ALU_AND  = 4'b0011;
    localparam ALU_OR   = 4'b0100;
    localparam ALU_XOR  = 4'b0101;
    localparam ALU_SLL  = 4'b0110;
    localparam ALU_SRL  = 4'b0111;
    localparam ALU_SLT  = 4'b1000;
    localparam ALU_SLTU = 4'b1001;
    localparam ALU_SRA  = 4'b1010;
    localparam ALU_Ap4  = 4'b1011;
    localparam ALU_Bout = 4'b1100;

    reg state;
    assign finish = state == 1'b1;
    initial begin
        state = 0;
    end

    // stateful ALU functional unit: latch inputs on EN, result ready one cycle later
    reg[3:0] ctrl_reg;
    reg[31:0] A_reg, B_reg;

    always @(posedge clk) begin
        if (EN & ~state) begin
            state <= 1'b1;
            ctrl_reg <= ALUControl;
            A_reg <= ALUA;
            B_reg <= ALUB;
        end
        else if (state) begin
            state <= 1'b0;
        end
    end

    wire[31:0] res_ADD  = A_reg + B_reg;
    wire[31:0] res_SUB  = A_reg - B_reg;
    wire[31:0] res_AND  = A_reg & B_reg;
    wire[31:0] res_OR   = A_reg | B_reg;
    wire[31:0] res_XOR  = A_reg ^ B_reg;
    wire[31:0] res_SLL  = A_reg << B_reg[4:0];
    wire[31:0] res_SRL  = A_reg >> B_reg[4:0];
    wire[31:0] res_SLT  = ($signed(A_reg) < $signed(B_reg)) ? 32'd1 : 32'd0;
    wire[31:0] res_SLTU = (A_reg < B_reg) ? 32'd1 : 32'd0;
    wire[31:0] res_SRA  = $signed(A_reg) >>> B_reg[4:0];
    wire[31:0] res_Ap4  = A_reg + 32'd4;
    wire[31:0] res_Bout = B_reg;

    assign res = {32{ctrl_reg == ALU_ADD}}  & res_ADD  |
                 {32{ctrl_reg == ALU_SUB}}  & res_SUB  |
                 {32{ctrl_reg == ALU_AND}}  & res_AND  |
                 {32{ctrl_reg == ALU_OR}}   & res_OR   |
                 {32{ctrl_reg == ALU_XOR}}  & res_XOR  |
                 {32{ctrl_reg == ALU_SLL}}  & res_SLL  |
                 {32{ctrl_reg == ALU_SRL}}  & res_SRL  |
                 {32{ctrl_reg == ALU_SLT}}  & res_SLT  |
                 {32{ctrl_reg == ALU_SLTU}} & res_SLTU |
                 {32{ctrl_reg == ALU_SRA}}  & res_SRA  |
                 {32{ctrl_reg == ALU_Ap4}}  & res_Ap4  |
                 {32{ctrl_reg == ALU_Bout}} & res_Bout ;

    assign zero = ~|res;

    assign overflow = (ctrl_reg == ALU_ADD) ? (~(A_reg[31] ^ B_reg[31]) & (res[31] ^ A_reg[31])) :
                      (ctrl_reg == ALU_SUB) ? ((A_reg[31] ^ B_reg[31]) & (res[31] ^ A_reg[31])) :
                      1'b0;

endmodule

`timescale 1ns / 1ps

module FU_mul(
    input clk, EN,
    input[31:0] A, B,
    output[31:0] res,
    output finish
);

    reg[6:0] state;
    assign finish = state[0] == 1'b1;
    initial begin
        state = 0;
    end

    // multiplication functional unit: 64-cycle latency modeled by a
    // shifting state register (7'b100_0000 -> ... -> 7'b000_0001)
    reg[31:0] A_reg, B_reg;
    wire[63:0] mulres;

    always @(posedge clk) begin
        if (EN & ~|state) begin
            state <= 7'b100_0000;
            A_reg <= A;
            B_reg <= B;
        end
        else begin
            state <= {1'b0, state[6:1]};
        end
    end

    multiplier mul(.CLK(clk), .A(A_reg), .B(B_reg), .P(mulres));

    assign res = mulres[31:0];

endmodule

`timescale 1ns / 1ps

module FU_div(
    input clk, EN,
    input[31:0] A, B,
    output[31:0] res,
    output finish
);

    wire res_valid;
    wire[63:0] divres;

    reg state;
    assign finish = res_valid & state;
    initial begin
        state = 0;
    end

    // division functional unit: AXI-style handshake with the divider IP
    reg A_valid, B_valid;
    reg[31:0] A_reg, B_reg;

    initial begin
        A_valid = 0;
        B_valid = 0;
    end

    always @(posedge clk) begin
        if (EN & ~state) begin
            A_reg <= A;
            B_reg <= B;
            A_valid <= 1'b1;
            B_valid <= 1'b1;
            state <= 1'b1;
        end
        else if (res_valid) begin
            A_valid <= 1'b0;
            B_valid <= 1'b0;
            state <= 1'b0;
        end
        else begin
            A_valid <= 1'b0;
            B_valid <= 1'b0;
        end
    end

    divider div(
        .aclk(clk),
        .s_axis_dividend_tvalid(A_valid),
        .s_axis_dividend_tdata(A_reg),
        .s_axis_divisor_tvalid(B_valid),
        .s_axis_divisor_tdata(B_reg),
        .m_axis_dout_tvalid(res_valid),
        .m_axis_dout_tdata(divres)
    );

    // quotient is the upper 32 bits of the divider result
    assign res = divres[63:32];

endmodule

`timescale 1ns / 1ps

module FU_jump(
	input clk, EN, JALR,
	input[3:0] cmp_ctrl,
	input[31:0] rs1_data, rs2_data, imm, PC,
	output[31:0] PC_jump, PC_wb,
	output is_jump, finish
);

	wire cmp_res;
    reg state;
    assign finish = state == 1'b1;
	initial begin
        state = 0;
    end

	// jump/branch functional unit: latch inputs on EN, result ready one cycle later
	reg JALR_reg;
	reg[3:0] cmp_ctrl_reg;
	reg[31:0] rs1_data_reg, rs2_data_reg, imm_reg, PC_reg;

	always @(posedge clk) begin
		if (EN & ~state) begin
			state <= 1'b1;
			JALR_reg <= JALR;
			cmp_ctrl_reg <= cmp_ctrl;
			rs1_data_reg <= rs1_data;
			rs2_data_reg <= rs2_data;
			imm_reg <= imm;
			PC_reg <= PC;
		end
		else if (state) begin
			state <= 1'b0;
		end
	end

	cmp_32 cmp(.a(rs1_data_reg), .b(rs2_data_reg), .ctrl(cmp_ctrl_reg[3:1]), .c(cmp_res));

	// jump target: JALR uses rs1 as base, branches/JAL use PC
	add_32 add_target(.a(JALR_reg ? rs1_data_reg : PC_reg), .b(imm_reg), .c(PC_jump));

	// return address
	add_32 add_wb(.a(PC_reg), .b(32'd4), .c(PC_wb));

	// unconditional jump (cmp_ctrl[0]) or condition met
	assign is_jump = cmp_ctrl_reg[0] | cmp_res;

endmodule

`timescale 1ns / 1ps

module FU_mem(
    input clk, EN, mem_w,
    input[2:0] bhw,
    input[31:0] rs1_data, rs2_data, imm,
    output[31:0] mem_data,
    output finish
);

    reg[1:0] state;
    assign finish = state[0] == 1'b1;
    initial begin
        state = 0;
    end

    // memory functional unit: 2-cycle latency modeled by a shifting
    // state register (2'b10 -> 2'b01 -> 2'b00)
    reg mem_w_reg;
    reg[2:0] bhw_reg;
    reg[31:0] rs1_data_reg, rs2_data_reg, imm_reg;

    wire[31:0] addr;

    always @(posedge clk) begin
        if (EN & ~|state) begin
            state <= 2'b10;
