`timescale 1ns / 1ps
// Testbench: run lab5 scoreboard core on rom.mem/ram.mem, check WB-stage writes.
module lab5_tb;
    reg clk, rst;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'd0),
        .debug_data(),
        .wb_addr(),
        .wb_data(),
        .clk_counter(),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0)
    );

    initial begin
        clk = 0;
        rst = 1;
        #4 rst = 0;
    end
    always #1 clk = ~clk;

    integer errors = 0;

    // expected (rd, value) writes, each must be observed at least once
    reg [31:0] exp_val [0:31];
    reg        exp_seen [0:31];
    reg [4:0]  exp_rd  [0:31];
    integer n_exp = 17;

    initial begin
        exp_rd[0]  = 5'd2; exp_val[0]  = 32'h00000008; // lw x2, 4(x0)
        exp_rd[1]  = 5'd4; exp_val[1]  = 32'h00000010; // lw x4, 8(x0)
        exp_rd[2]  = 5'd1; exp_val[2]  = 32'h00000018; // add x1, x2, x4
        exp_rd[3]  = 5'd1; exp_val[3]  = 32'h00000017; // addi x1, x1, -1
        exp_rd[4]  = 5'd5; exp_val[4]  = 32'h00000014; // lw x5, 12(x0)
        exp_rd[5]  = 5'd6; exp_val[5]  = 32'hFFFF0000; // lw x6, 16(x0)
        exp_rd[6]  = 5'd7; exp_val[6]  = 32'h0FFF0000; // lw x7, 20(x0)
        exp_rd[7]  = 5'd1; exp_val[7]  = 32'h00000008; // sub x1, x4, x2
        exp_rd[8]  = 5'd1; exp_val[8]  = 32'hFFFFFFFD; // addi x1, x10, -3
        exp_rd[9]  = 5'd1; exp_val[9]  = 32'h00004000; // lui x1, 4
        exp_rd[10] = 5'd1; exp_val[10] = 32'h00000048; // jal x1, 12
        exp_rd[11] = 5'd1; exp_val[11] = 32'hFFFF0050; // auipc x1, 0xffff0
        exp_rd[12] = 5'd8; exp_val[12] = 32'h01FFE000; // div x8, x7, x2
        exp_rd[13] = 5'd9; exp_val[13] = 32'h00000140; // mul x9, x4, x5
        exp_rd[14] = 5'd9; exp_val[14] = 32'h0FFF0000; // mul x9, x8, x2
        exp_rd[15] = 5'd2; exp_val[15] = 32'h00000004; // addi x2, x0, 4
        exp_rd[16] = 5'd1; exp_val[16] = 32'h00000068; // jalr x1, 0(x0)
    end

    // monitor WB writes (regfile latches at negedge)
    integer k;
    always @(negedge clk) begin
        if (!rst && core.RegWrite_ctrl && core.rd_ctrl != 0) begin
            for (k = 0; k < n_exp; k = k + 1)
                if (core.rd_ctrl == exp_rd[k] && core.wt_data_WB === exp_val[k])
                    exp_seen[k] = 1;
        end
    end

    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1) exp_seen[i] = 0;
        #4000;
        for (i = 0; i < n_exp; i = i + 1) begin
            if (!exp_seen[i]) begin
                errors = errors + 1;
                $display("FAIL: never observed write x%0d = %h", exp_rd[i], exp_val[i]);
            end
        end
        if (errors == 0) $display("LAB5 PASS");
        else             $display("LAB5 FAIL: %0d errors", errors);
        $finish;
    end

endmodule

