```verilog
`timescale 1ns / 1ps
`include "CtrlDefine.vh"

module RS #(
    parameter FU = `FU_ALU,   // 3-bit FU type, forms the tag {FU, index}
    parameter num = 3         // number of entries
)(
    input clk, rst,

    // issue (allocate)
    input selected,           // allocate a new entry this cycle
    output [7:0] free_rs,     // tag of a free entry, 0 if none
    input [4:0] op,
    input [7:0] Qj, Qk,       // producer tags (0 = value ready)
    input [31:0] Vj, Vk,      // operand values (valid when Q == 0)
    input [31:0] A,           // address/imm field
    input [31:0] pc_IS,

    // dispatch to FU
    output reg en_FU,
    output [31:0] vj, vk,
    output [4:0] op_out,
    output [31:0] A_o,
    output [31:0] pc_FU,

    // tag of the entry currently in the FU (its result goes to CDB)
    output [7:0] cdb_rs_rd,

    // CDB snoop
    input [7:0] cdb_rs_num,
    input [31:0] cdb_data,

    output [31:0] pc_debug
);
```

Entry storage: I'll use arrays rather than the bit-packed `MAXLEN record, but the defines suggest a packed layout. Simpler: separate arrays:

```
reg busy [0:num-1];
reg [4:0] op_r [0:num-1];
reg [7:0] Q1 [0:num-1], Q2 [0:num-1];
reg [31:0] V1 [0:num-1], V2 [0:num-1], A_r [0:num-1], PC_r [0:num-1];
```

