`timescale 1ns / 1ps

module FU_mem(
    input clk, EN, mem_w,
    input[2:0] bhw,
    input[31:0] rs1_data, rs2_data, imm,
    output[31:0] mem_data,
    output finish
);

    reg[1:0] state;
    assign finish = state[0] == 1'b1;
    initial begin
        state = 0;
    end

    // memory functional unit: 2-cycle latency modeled by a shifting
    // state register (2'b10 -> 2'b01 -> 2'b00)
    reg mem_w_reg;
    reg[2:0] bhw_reg;
    reg[31:0] rs1_data_reg, rs2_data_reg, imm_reg;

    wire[31:0] addr;

    always @(posedge clk) begin
        if (EN & ~|state) begin
            state <= 2'b10;
            mem_w_reg <= mem_w;
            bhw_reg <= bhw;
            rs1_data_reg <= rs1_data;
            rs2_data_reg <= rs2_data;
            imm_reg <= imm;
        end
        else begin
            state <= {1'b0, state[1]};
        end
    end

    add_32 add_addr(.a(rs1_data_reg), .b(imm_reg), .c(addr));

    RAM_B ram(
        .addra(addr),
        .clka(clk),
        .dina(rs2_data_reg),
        .wea(mem_w_reg & state[1]),
        .douta(mem_data),
        .mem_u_b_h_w(bhw_reg),
        .finish(finish)
    );

endmodule

`timescale 1ns / 1ps

module RAM_B(
    input [31:0] addra,
    input clka,      // normal clock
    input[31:0] dina,
    input wea,
    output[31:0] douta,
    input[2:0] mem_u_b_h_w,
    input finish
);

    localparam SIZE = 512;
    localparam ADDR_LINE = $clog2(SIZE);
    localparam SIM_UART_ADDR = 32'h10000000;

    reg[7:0] data[0:SIZE-1];

    initial	begin
        $readmemh("ram.mem", data);
    end

    wire uart_sel = addra == SIM_UART_ADDR;
    // the RAM is aliased over the whole address space via the low address bits
    wire[ADDR_LINE-1:0] addr = addra[ADDR_LINE-1:0];

    // mem_u_b_h_w[1]=1 -> word, mem_u_b_h_w[0]=1 -> halfword, otherwise byte
    wire wr_word = mem_u_b_h_w[1];
    wire wr_half = mem_u_b_h_w[0];

    // byte-addressable write logic; writes to the simulated UART are
    // redirected to the UART simulation instead of the memory array
    always @ (negedge clka) begin
        if (wea & ~uart_sel) begin
            data[addr] <= dina[7:0];
            if (wr_half | wr_word)
                data[addr + 1] <= dina[15:8];
            if (wr_word) begin
                data[addr + 2] <= dina[23:16];
                data[addr + 3] <= dina[31:24];
            end
        end
        if (wea & uart_sel) begin
            uart_addr_valid <= 1'b1;
            uart_char <= dina[7:0];
        end
    end

    // combinational read; mem_u_b_h_w[2]=1 -> unsigned (zero-extend)
    wire[31:0] rd_word = {data[addr + 3], data[addr + 2], data[addr + 1], data[addr]};
    wire[31:0] rd_half = mem_u_b_h_w[2] ? {16'b0, data[addr + 1], data[addr]} :
                         {{16{data[addr + 1][7]}}, data[addr + 1], data[addr]};
    wire[31:0] rd_byte = mem_u_b_h_w[2] ? {24'b0, data[addr]} :
                         {{24{data[addr][7]}}, data[addr]};

    assign douta = uart_sel ? 32'b0 :
                   wr_word  ? rd_word :
                   wr_half  ? rd_half :
                              rd_byte;

    // simulated UART output: latch the character of a store to
    // SIM_UART_ADDR and print it when the memory operation finishes
    reg uart_addr_valid;
    reg[7:0] uart_char;

    initial begin
        uart_addr_valid = 1'b0;
    end

    always @ (posedge clka) begin
        if (finish & uart_addr_valid) begin
            $write("%c", uart_char);
            uart_addr_valid <= 1'b0;
        end
    end

endmodule

